insert into questions (slug, section, skill, difficulty, tier, four_d, passage, time_target_seconds, stem, choices, correct_index, explanation, reviewed) values
  ('seed-001', 'writing', 'transitions', 2, 'gate', 'discernment', null, 15, 'The results were inconclusive. ______, the team repeated the experiment.', '["Therefore", "However", "Similarly", "Nevertheless"]'::jsonb, 0, 'The second sentence is a consequence of the first, so a cause-and-effect transition fits.', false),
  ('seed-002', 'math', 'linear-equations', 1, 'gate', 'diligence', null, 15, 'If 3x + 6 = 21, what is x?', '["3", "5", "7", "9"]'::jsonb, 1, 'Subtract 6 to get 3x = 15, then divide by 3.', false),
  ('seed-003', 'reading', 'vocabulary-in-context', 3, 'gate', 'description', null, 15, 'The library reserved the top shelf for its rare atlases. As used here, ''reserved'' most nearly means:', '["set aside", "shy", "doubtful", "booked"]'::jsonb, 0, 'Context governs the meaning, not the most common definition. A shelf kept for one purpose is ''set aside''; ''shy'' is the meaning for people.', false),
  ('m-001', 'math', 'linear-equations', 1, 'gate', 'diligence', null, 15, 'If 5x − 4 = 31, what is x?', '["5", "6", "7", "35"]'::jsonb, 2, 'Undo operations in reverse: add 4 to get 5x = 35, then divide by 5.', false),
  ('m-002', 'math', 'linear-functions', 2, 'gate', 'description', null, 15, 'A phone plan costs $12 per month plus a one-time $30 fee. Which expression gives the total cost, in dollars, for m months?', '["30m + 12", "12m + 30", "42m", "12(m + 30)"]'::jsonb, 1, 'The amount that repeats each month multiplies m; the one-time fee is added once.', false),
  ('m-003', 'math', 'linear-functions', 2, 'gate', 'diligence', null, 15, 'What is the slope of the line through (1, 4) and (3, 10)?', '["2", "3", "6", "1/3"]'::jsonb, 1, 'Slope is change in y over change in x: (10 − 4) / (3 − 1) = 6 / 2 = 3.', false),
  ('m-004', 'math', 'linear-equations-two-variables', 3, 'gate', 'delegation', null, 15, 'What is the y-intercept of the line 2x + 3y = 12?', '["2", "3", "4", "6"]'::jsonb, 2, 'The y-intercept is where x = 0. Plug in x = 0 to get 3y = 12, so y = 4. No need to rewrite in slope-intercept form.', false),
  ('m-005', 'math', 'systems-of-linear-equations', 3, 'gate', 'delegation', null, 15, 'If x + y = 10 and x − y = 4, what is x?', '["3", "6", "7", "14"]'::jsonb, 2, 'Add the equations so y cancels: 2x = 14, so x = 7. Elimination is faster than substitution when the y terms are opposites.', false),
  ('m-006', 'math', 'linear-inequalities', 2, 'gate', 'diligence', null, 15, 'Which value of x satisfies −2x > 6?', '["−4", "−3", "0", "3"]'::jsonb, 0, 'Dividing by a negative flips the inequality: x < −3. Only −4 is less than −3; −3 itself is not.', false),
  ('m-007', 'math', 'equivalent-expressions', 2, 'gate', 'description', null, 15, 'Which expression is equivalent to 3(x + 4) − x?', '["2x + 4", "2x + 12", "4x + 12", "3x + 4"]'::jsonb, 1, 'Distribute first: 3x + 12 − x. Then combine like terms: 2x + 12.', false),
  ('m-008', 'math', 'nonlinear-equations', 2, 'gate', 'diligence', null, 15, 'If x² = 49 and x < 0, what is x?', '["−7", "−49", "7", "−1/7"]'::jsonb, 0, 'x² = 49 has two solutions, 7 and −7. The condition x < 0 rules out 7.', false),
  ('m-009', 'math', 'nonlinear-functions', 3, 'gate', 'diligence', null, 15, 'If f(x) = x² − 3x, what is f(4)?', '["−4", "4", "8", "28"]'::jsonb, 1, 'Substitute 4 for every x: 4² − 3(4) = 16 − 12 = 4.', false),
  ('m-010', 'math', 'percentages', 1, 'gate', 'diligence', null, 15, 'What is 20% of 45?', '["4.5", "9", "20", "25"]'::jsonb, 1, '20% is one fifth, and 45 ÷ 5 = 9.', false),
  ('m-011', 'math', 'ratios-rates-proportions', 2, 'gate', 'delegation', null, 15, 'A recipe uses 3 cups of flour for every 2 cups of sugar. How many cups of flour go with 8 cups of sugar?', '["10", "12", "16", "24"]'::jsonb, 1, 'Sugar went from 2 to 8, a factor of 4, so flour goes from 3 to 3 × 4 = 12.', false),
  ('m-012', 'math', 'percentages', 3, 'gate', 'diligence', null, 15, 'An $80 jacket is discounted 25%, and then the sale price is discounted another 10%. What is the final price?', '["$52", "$54", "$56", "$58"]'::jsonb, 1, 'Apply the discounts one at a time: 80 × 0.75 = 60, then 60 × 0.90 = 54. Taking 35% off at once gives the trap answer $52.', false),
  ('m-013', 'math', 'units', 2, 'gate', 'delegation', null, 15, 'A car travels at 60 miles per hour. How many miles does it travel in 25 minutes?', '["15", "25", "36", "150"]'::jsonb, 1, '60 miles per hour is 1 mile per minute, so 25 minutes covers 25 miles. Convert to the unit the question uses.', false),
  ('m-014', 'math', 'one-variable-data', 2, 'gate', 'discernment', null, 15, 'What is the median of the data set 4, 7, 7, 9, 13?', '["7", "8", "9", "40"]'::jsonb, 0, 'The median is the middle value of the ordered list, which is 7. The mean is 8, which is the trap.', false),
  ('m-015', 'math', 'probability', 3, 'gate', 'diligence', null, 15, 'A bag has 3 red, 5 blue, and 2 green marbles. What is the probability that a randomly chosen marble is NOT blue?', '["1/5", "3/10", "1/2", "7/10"]'::jsonb, 2, '5 of the 10 marbles are not blue (3 red + 2 green), so the probability is 5/10 = 1/2. Watch for NOT in the question.', false),
  ('m-016', 'math', 'area-volume', 1, 'gate', 'delegation', null, 15, 'What is the area of a circle with radius 3?', '["3π", "6π", "9π", "27π"]'::jsonb, 2, 'Area is πr², so π × 3² = 9π. 6π is the circumference, a different formula.', false),
  ('m-017', 'math', 'lines-angles-triangles', 2, 'gate', 'diligence', null, 15, 'Two angles of a triangle measure 48° and 67°. What is the third angle?', '["55°", "65°", "75°", "115°"]'::jsonb, 1, 'Angles in a triangle sum to 180°: 180 − 48 − 67 = 65.', false),
  ('m-018', 'math', 'right-triangles-trig', 2, 'gate', 'delegation', null, 15, 'A right triangle has legs of length 6 and 8. What is the length of the hypotenuse?', '["10", "12", "14", "100"]'::jsonb, 0, 'Recognize the 3-4-5 triple scaled by 2, or use a² + b² = c²: 36 + 64 = 100, so c = 10.', false),
  ('m-019', 'math', 'right-triangles-trig', 4, 'gate', 'discernment', null, 15, 'In right triangle ABC, angle C is 90° and sin A = 3/5. What is cos B?', '["3/5", "4/5", "5/3", "3/4"]'::jsonb, 0, 'A and B are complementary, and the sine of an angle equals the cosine of its complement. The side opposite A is the side adjacent to B.', false),
  ('m-020', 'math', 'circles', 4, 'gate', 'diligence', null, 15, 'What is the center of the circle (x − 2)² + (y + 5)² = 36?', '["(2, −5)", "(−2, 5)", "(2, 5)", "(6, 6)"]'::jsonb, 0, 'The form (x − h)² + (y − k)² = r² has center (h, k). y + 5 means k = −5, so the center is (2, −5).', false),
  ('m-s01', 'math', 'linear-functions', 3, 'session', 'description', null, 75, 'A tank holds 500 liters of water and drains at a constant rate of 20 liters per minute. After how many minutes will 140 liters remain?', '["7", "18", "25", "32"]'::jsonb, 1, 'Write the situation as an equation: 500 − 20t = 140. Then 20t = 360, so t = 18.', false),
  ('m-s02', 'math', 'systems-of-linear-equations', 4, 'session', 'delegation', null, 75, 'Adult tickets cost $12 and student tickets cost $7. A group bought 15 tickets for a total of $145. How many adult tickets did the group buy?', '["5", "7", "8", "10"]'::jsonb, 2, 'Set up a + s = 15 and 12a + 7s = 145. Substitute s = 15 − a: 12a + 105 − 7a = 145, so 5a = 40 and a = 8.', false),
  ('m-s03', 'math', 'nonlinear-equations', 4, 'session', 'delegation', null, 75, 'What is the sum of the solutions to x² − 5x − 14 = 0?', '["−5", "5", "9", "14"]'::jsonb, 1, 'For ax² + bx + c = 0 the solutions sum to −b/a = 5, no factoring needed. Check: (x − 7)(x + 2) gives 7 and −2, which sum to 5.', false),
  ('m-s04', 'math', 'nonlinear-functions', 5, 'session', 'diligence', null, 75, 'The function h(t) = −16t² + 64t + 5 gives a ball''s height, in feet, t seconds after it is thrown. What is the ball''s maximum height, in feet?', '["5", "64", "69", "133"]'::jsonb, 2, 'The vertex is at t = −b/(2a) = −64/(−32) = 2. Then h(2) = −64 + 128 + 5 = 69.', false),
  ('m-s05', 'math', 'two-variable-data', 3, 'session', 'discernment', null, 75, 'A line of best fit for hours studied, x, and test score, y, is y = 4.5x + 62. Which is the best interpretation of 4.5?', '["Each additional hour studied is associated with a predicted increase of 4.5 points.", "A student who studies 0 hours is predicted to score 4.5.", "Studying causes scores to rise by exactly 4.5 points per hour.", "The average student studied 4.5 hours."]'::jsonb, 0, 'The slope is the predicted change in y for each one-unit increase in x. A best-fit line shows association, not proof of cause.', false),
  ('m-s06', 'math', 'sample-inference', 4, 'session', 'discernment', null, 75, 'A school surveyed 50 students chosen at random from its robotics club and found that 80% wanted a longer lunch period. Which conclusion is best supported?', '["About 80% of all students at the school want a longer lunch period.", "About 80% of robotics club members likely want a longer lunch period.", "Exactly 40 students at the school want a longer lunch period.", "Most students at the school are in the robotics club."]'::jsonb, 1, 'A random sample only supports conclusions about the group it was drawn from, which here is the robotics club, not the whole school.', false),
  ('m-s07', 'math', 'percentages', 4, 'session', 'diligence', null, 75, 'A town''s population grew from 2,000 to 2,500 and then decreased by 20%. What is the final population?', '["1,500", "2,000", "2,100", "2,400"]'::jsonb, 1, 'The 20% is taken from 2,500: 2,500 × 0.8 = 2,000. A 25% rise followed by a 20% fall cancels because the percents use different bases.', false),
  ('m-s08', 'math', 'area-volume', 4, 'session', 'delegation', null, 75, 'A cylinder has a radius of 3 cm and a volume of 72π cm³. What is its height, in cm?', '["4", "6", "8", "24"]'::jsonb, 2, 'Volume of a cylinder is πr²h, so 9πh = 72π and h = 8.', false),
  ('m-s09', 'math', 'equivalent-expressions', 5, 'session', 'description', null, 75, 'If (x + a)² = x² + 10x + c for all values of x, what is c?', '["5", "10", "25", "100"]'::jsonb, 2, 'Expanding gives x² + 2ax + a². Matching 2a = 10 gives a = 5, so c = a² = 25.', false),
  ('m-s10', 'math', 'linear-equations', 5, 'session', 'discernment', null, 75, 'For what value of k does the equation 3(x − 2) = kx + 4 have no solution?', '["−3", "0", "3", "6"]'::jsonb, 2, 'Expand to 3x − 6 = kx + 4. If k = 3 the x terms cancel and leave −6 = 4, which is never true. Any other k gives exactly one solution.', false),
  ('w-001', 'writing', 'boundaries', 2, 'gate', 'diligence', null, 15, 'Which choice correctly completes the sentence? The bridge opened in ______ still crossed by thousands of drivers every day.', '["1932, it is", "1932; it is", "1932 it is", "1932, it, is"]'::jsonb, 1, 'Both halves are complete sentences, so they need a semicolon or a period. A comma alone between them is a comma splice.', false),
  ('w-002', 'writing', 'form-structure-sense', 2, 'gate', 'diligence', null, 15, 'The box of old letters ______ stored in the attic for decades.', '["was", "were", "are", "have been"]'::jsonb, 0, 'The subject is ''box'', not ''letters''. Skip the ''of'' phrase to find it, then use a singular verb.', false),
  ('w-003', 'writing', 'form-structure-sense', 3, 'gate', 'diligence', null, 15, 'The committee announced ______ decision on Friday.', '["its", "it''s", "their", "they''re"]'::jsonb, 0, 'A committee acting as one unit takes a singular pronoun. ''Its'' shows possession; ''it''s'' means ''it is''.', false),
  ('w-004', 'writing', 'transitions', 3, 'gate', 'discernment', null, 15, 'Solar panels have become far cheaper over the past decade. ______, many homeowners still name cost as the main reason they haven''t installed them.', '["Consequently", "For example", "Nevertheless", "Similarly"]'::jsonb, 2, 'The second sentence goes against what the first would lead you to expect, so it needs a contrast word.', false),
  ('w-005', 'writing', 'transitions', 2, 'gate', 'discernment', null, 15, 'Octopuses can change color in milliseconds. ______, some species can also change the texture of their skin.', '["In addition", "Instead", "In contrast", "As a result"]'::jsonb, 0, 'The second sentence adds another ability of the same kind, so an addition transition fits.', false),
  ('w-006', 'reading', 'vocabulary-in-context', 3, 'gate', 'description', null, 15, 'The senator''s speech was so ______ that even her opponents praised its clarity.', '["lucid", "verbose", "hesitant", "obscure"]'::jsonb, 0, 'The clue is ''clarity''. ''Lucid'' means clear and easy to follow.', false),
  ('w-007', 'reading', 'vocabulary-in-context', 4, 'gate', 'description', null, 15, 'Far from being ______, the scientist''s claim had been tested in dozens of independent labs.', '["speculative", "rigorous", "celebrated", "obsolete"]'::jsonb, 0, '''Far from being'' signals the opposite of what follows. A claim tested many times is the opposite of ''speculative'', meaning based on guesswork.', false),
  ('w-008', 'reading', 'vocabulary-in-context', 2, 'gate', 'description', null, 15, 'In ''The coach''s plan was sound,'' the word ''sound'' most nearly means:', '["noisy", "reasonable", "asleep", "complete"]'::jsonb, 1, 'A plan described as sound is well reasoned. Replace the word with each choice and keep the one that makes sense.', false),
  ('w-009', 'writing', 'form-structure-sense', 3, 'gate', 'diligence', null, 15, 'Both ______ findings surprised the review board.', '["researcher''s", "researchers''", "researchers", "researchers''s"]'::jsonb, 1, '''Both'' means more than one researcher, and the findings belong to them, so use the plural possessive: researchers''.', false),
  ('w-010', 'writing', 'form-structure-sense', 4, 'gate', 'diligence', null, 15, 'Walking into the gallery, ______', '["the paintings impressed Lena.", "Lena was impressed by the paintings.", "the paintings were impressive to Lena.", "impressive paintings greeted Lena."]'::jsonb, 1, 'The person doing the walking must come right after the comma. Paintings can''t walk, so Lena has to be the subject.', false),
  ('w-011', 'reading', 'vocabulary-in-context', 5, 'gate', 'description', null, 15, 'The novelist''s later work has a ______ style: every sentence is pared down, with no word wasted.', '["laconic", "florid", "meandering", "whimsical"]'::jsonb, 0, 'The colon says the blank is defined by what follows. ''Laconic'' means using very few words.', false),
  ('w-012', 'writing', 'form-structure-sense', 3, 'gate', 'diligence', null, 15, 'By the time the rescue team arrived, the hikers ______ for nearly two days.', '["wait", "have waited", "had been waiting", "will wait"]'::jsonb, 2, 'The waiting happened before another past event (the arrival), so use the past perfect: ''had been waiting''.', false),
  ('w-013', 'writing', 'form-structure-sense', 4, 'gate', 'discernment', null, 15, 'The population of Tokyo is larger than ______.', '["any city in Europe", "that of any city in Europe", "any European city''s people", "Europe"]'::jsonb, 1, 'Compare like with like: a population to a population. ''That of'' stands for ''the population of''.', false),
  ('r-s01', 'reading', 'central-ideas', 3, 'session', 'discernment', 'Urban beekeeping has grown quickly in many cities, and supporters say rooftop hives help pollinate city gardens. Some ecologists, however, warn that adding large numbers of honeybees can crowd out native bees, which compete for the same limited flowers. They suggest that planting more kinds of flowering plants may do more for pollinators than adding hives.', 75, 'Which choice best states the main idea of the text?', '["Urban beekeeping is banned in most cities.", "Some ecologists caution that adding honeybee hives may not be the best way to help city pollinators.", "Honeybees pollinate flowers more efficiently than native bees do.", "Rooftop gardens cannot survive without honeybees."]'::jsonb, 1, 'The text sets up a popular idea and then gives the ecologists'' warning and alternative. The main idea is that caution, not a detail.', false),
  ('r-s02', 'reading', 'inferences', 4, 'session', 'discernment', 'Researchers gave two groups of students the same set of math problems. One group was told the problems measured natural talent; the other was told they measured skills that improve with practice. Students in the second group attempted more of the difficult problems. This suggests that ______', 75, 'Which choice most logically completes the text?', '["the problems given to the second group were easier.", "how students understand a task''s purpose may affect how long they persist with it.", "natural talent has no effect on math performance.", "students in the first group were less skilled at math."]'::jsonb, 1, 'Both groups got the same problems, so the only difference was what they were told. The conclusion must stay within what that difference can show.', false),
  ('r-s03', 'reading', 'command-of-evidence-textual', 4, 'session', 'discernment', null, 75, 'A student claims that the narrator of a story values independence over comfort. Which quotation from the story most directly supports the claim?', '["\"I left the warm house before dawn, preferring a cold road I had chosen to a soft bed someone else had made.\"", "\"The kitchen always smelled of bread and coffee.\"", "\"My brother laughed whenever I tripped over the doorstep.\"", "\"In winter, the river froze so thick that wagons could cross it.\""]'::jsonb, 0, 'Only the first quotation sets comfort (warm house, soft bed) against a choice the narrator makes for themself, which is exactly the claim.', false),
  ('r-s04', 'reading', 'command-of-evidence-quantitative', 4, 'session', 'diligence', 'A survey recorded the share of students who read for fun at least once a week: 42% in 2015, 38% in 2018, 31% in 2021, and 33% in 2024.', 75, 'A researcher claims that weekly reading for fun declined steadily from 2015 to 2024. Which choice best describes the data in relation to the claim?', '["It supports the claim, because each survey year was lower than the one before.", "It weakens the claim, because the share rose slightly from 2021 to 2024.", "It supports the claim, because the 2024 share was lower than the 2015 share.", "It weakens the claim, because the share never fell below 40%."]'::jsonb, 1, '''Steadily'' means every step goes down. Check each pair: 31% to 33% is a rise, so the data do not fully support the claim.', false),
  ('r-s05', 'reading', 'text-structure-purpose', 3, 'session', 'discernment', 'Many people assume that deserts are lifeless. Yet after a rare heavy rain, the Atacama Desert in Chile can burst into bloom, covering miles of ground with purple and pink flowers. Seeds that lay dormant in the soil for years sprout within days.', 75, 'Which choice best describes the overall structure of the text?', '["It presents a common belief and then gives an example that challenges it.", "It compares two deserts and explains why one gets more rain.", "It describes an experiment and reports its results.", "It argues that deserts should be protected from development."]'::jsonb, 0, '''Many people assume'' introduces a belief; ''Yet'' turns to the blooming desert as a counterexample.', false),
  ('r-s06', 'reading', 'cross-text-connections', 5, 'session', 'discernment', 'Text 1: Some historians argue that the printing press spread new ideas mainly by lowering the cost of books.
